mapper.select:
SELECT o.id, o.order_no, o.supplier_id, o.supplier_code_snapshot AS supplier_code, o.supplier_name_snapshot AS supplier_name, o.purchaser_id, e.actual_name AS purchaser_name, o.warehouse_id, o.warehouse_code_snapshot AS warehouse_code, o.warehouse_name_snapshot AS warehouse_name, o.planned_arrival_date, o.status, o.total_amount, CASE WHEN agg.planned_total IS NOT NULL AND agg.planned_total > 0 THEN ROUND(agg.received_total / agg.planned_total, 4) ELSE NULL END AS received_progress, o.remark, o.cancel_reason, o.short_close_reason, o.submitted_at, o.cancelled_at, o.short_closed_at, o.version, o.created_at, o.updated_at FROM purchase_order o LEFT JOIN t_employee e ON e.employee_id = o.purchaser_id AND e.deleted_flag = FALSE LEFT JOIN ( SELECT purchase_order_id, SUM(planned_quantity) AS planned_total, SUM(received_quantity) AS received_total FROM purchase_order_item WHERE deleted = FALSE GROUP BY purchase_order_id ) agg ON agg.purchase_order_id = o.id WHERE o.deleted = FALSE
AND o.order_no ILIKE CONCAT('%', #{query.orderNo}, '%')
AND o.supplier_id = #{query.supplierId}
AND o.purchaser_id = #{query.purchaserId}
AND o.warehouse_id = #{query.warehouseId}
AND o.status = #{query.status}
AND o.created_at >= #{query.createdFrom}
AND o.created_at < #{query.createdTo}
ORDER BY o.created_at DESC, o.id DESC

mapper.update:
UPDATE purchase_order
SET deleted    = TRUE,
    version    = version + 1,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{operator}
WHERE id = #{id}
  AND version = #{version}
  AND deleted = FALSE
